-- 7. INSERT ~350 FOOD POLLS, OPTIONS, AND VOTES
-- Setup temporary helper table for deterministic poll generation
DROP TEMPORARY TABLE IF EXISTS temp_polls;
CREATE TEMPORARY TABLE temp_polls (p_idx INT PRIMARY KEY, p_date DATE, is_active BIT(1));

    SELECT p_date, is_active FROM temp_polls ORDER BY p_idx;
    

    SELECT 
        CASE (p.id % 4)
            WHEN 0 THEN 'Paneer Butter Masala'
            WHEN 1 THEN 'Kadai Paneer'
            WHEN 2 THEN 'Shahi Paneer'
            ELSE 'Veg Pulao'
        END AS food_name,
        p.id AS poll_id
    FROM food_polls p
    WHERE p.poll_date >= '2025-09-25';

    SELECT 
        CASE (p.id % 4)
            WHEN 0 THEN 'Chole Bhature'
            WHEN 1 THEN 'Mix Veg'
            WHEN 2 THEN 'Dum Aloo'
            ELSE 'Jeera Rice'
        END AS food_name,
        p.id AS poll_id
    FROM food_polls p
    WHERE p.poll_date >= '2025-09-25';

    SELECT 
        CASE (p.id % 4)
            WHEN 0 THEN 'Rajma Chawal'
            WHEN 1 THEN 'Kadhi Pakoda'
            WHEN 2 THEN 'Bhindi Masala'
            ELSE 'Poha'
        END AS food_name,
        p.id AS poll_id
    FROM food_polls p
    WHERE p.poll_date >= '2025-09-25';

    SELECT 
        CASE (p.id % 4)
            WHEN 0 THEN 'Dal Tadka'
            WHEN 1 THEN 'Aloo Gobi'
            WHEN 2 THEN 'Dal Fry'
            ELSE 'Idli Sambhar'
        END AS food_name,
        p.id AS poll_id
    FROM food_polls p
    WHERE p.poll_date >= '2025-09-25';
    
