    SELECT 
        c.created_at,
        1,
        CONCAT('✅ Your complaint on "', c.type, '" has been resolved.'),
        c.user_id
    FROM complaint c
    WHERE c.resolved = 1 AND c.user_id IN (SELECT id FROM users WHERE email LIKE '%.demo@messo.com')
    LIMIT 600;
    
